  1 | import { useEffect, useRef, useCallback } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | interface AudioEngineCallbacks {
  5 |   onTimeUpdate: (time: number) => void;
  6 |   onDurationChange: (duration: number) => void;
  7 |   onEnded: () => void;
  8 |   onError: (error: string) => void;
  9 |   onLoadStart: () => void;
 10 |   onCanPlay: () => void;
 11 | }
 12 | 
 13 | export function useAudioEngine(callbacks: AudioEngineCallbacks) {
 14 |   const audioRef = useRef<HTMLAudioElement | null>(null);
 15 |   const callbacksRef = useRef(callbacks);
 16 |   const trackUrlRef = useRef<string | null>(null);
 17 | 
 18 |   // Keep callbacks ref fresh
 19 |   callbacksRef.current = callbacks;
 20 | 
 21 |   // Initialize audio element once
 22 |   useEffect(() => {
 23 |     const audio = new Audio();
 24 |     audio.preload = "auto";
 25 | 
 26 |     const onTimeUpdate = () => callbacksRef.current.onTimeUpdate(audio.currentTime);
 27 |     const onDurationChange = () => callbacksRef.current.onDurationChange(audio.duration);
 28 |     const onEnded = () => callbacksRef.current.onEnded();
 29 |     const onError = () => {
 30 |       const msg = audio.error
 31 |         ? `Erro de áudio: ${audio.error.message || `código ${audio.error.code}`}`
 32 |         : "Erro desconhecido ao carregar áudio";
 33 |       callbacksRef.current.onError(msg);
 34 |     };
 35 |     const onLoadStart = () => callbacksRef.current.onLoadStart();
 36 |     const onCanPlay = () => callbacksRef.current.onCanPlay();
 37 | 
 38 |     audio.addEventListener("timeupdate", onTimeUpdate);
 39 |     audio.addEventListener("durationchange", onDurationChange);
 40 |     audio.addEventListener("ended", onEnded);
 41 |     audio.addEventListener("error", onError);
 42 |     audio.addEventListener("loadstart", onLoadStart);
 43 |     audio.addEventListener("canplay", onCanPlay);
 44 | 
 45 |     audioRef.current = audio;
 46 | 
 47 |     return () => {
 48 |       audio.removeEventListener("timeupdate", onTimeUpdate);
 49 |       audio.removeEventListener("durationchange", onDurationChange);
 50 |       audio.removeEventListener("ended", onEnded);
 51 |       audio.removeEventListener("error", onError);
 52 |       audio.removeEventListener("loadstart", onLoadStart);
 53 |       audio.removeEventListener("canplay", onCanPlay);
 54 |       audio.pause();
 55 |       audio.src = "";
 56 |       audioRef.current = null;
 57 |     };
 58 |   }, []);
 59 | 
 60 |   const loadTrack = useCallback((track: Track) => {
 61 |     const audio = audioRef.current;
 62 |     if (!audio) return;
 63 | 
 64 |     // Revoke previous blob URL if any
 65 |     if (trackUrlRef.current) {
 66 |       URL.revokeObjectURL(trackUrlRef.current);
 67 |       trackUrlRef.current = null;
 68 |     }
 69 | 
 70 |     if (track.src) {
 71 |       audio.src = track.src;
 72 |     } else {
 73 |       // No source — generate a silent placeholder so the player still works visually
 74 |       audio.src = "";
 75 |     }
 76 |     audio.load();
 77 |   }, []);
 78 | 
 79 |   const play = useCallback(() => {
 80 |     const audio = audioRef.current;
 81 |     if (!audio || !audio.src) return;
 82 |     audio.play().catch((err) => {
 83 |       callbacksRef.current.onError(`Erro ao reproduzir: ${err.message}`);
 84 |     });
 85 |   }, []);
 86 | 
 87 |   const pause = useCallback(() => {
 88 |     audioRef.current?.pause();
 89 |   }, []);
 90 | 
 91 |   const stop = useCallback(() => {
 92 |     const audio = audioRef.current;
 93 |     if (!audio) return;
 94 |     audio.pause();
 95 |     audio.currentTime = 0;
 96 |   }, []);
 97 | 
 98 |   const seek = useCallback((time: number) => {
 99 |     const audio = audioRef.current;
100 |     if (!audio) return;
101 |     audio.currentTime = time;
102 |   }, []);
103 | 
104 |   const setVolume = useCallback((volume: number) => {
105 |     const audio = audioRef.current;
106 |     if (!audio) return;
107 |     audio.volume = volume / 100;
108 |   }, []);
109 | 
110 |   const setPlaybackRate = useCallback((rate: number) => {
111 |     const audio = audioRef.current;
112 |     if (!audio) return;
113 |     audio.playbackRate = rate;
114 |   }, []);
115 | 
116 |   return {
117 |     loadTrack,
118 |     play,
119 |     pause,
120 |     stop,
121 |     seek,
122 |     setVolume,
123 |     setPlaybackRate,
124 |     audioRef,
125 |   };
126 | }
